#!/usr/bin/env node
// Generates src/abi.generated.ts from the compiled contract and pins its sha256 in src/abi-hash.json.
//
//   node scripts/gen-abi.mjs          # (from web/) regenerate from ../out/PixelPit.sol/PixelPit.json
//   node scripts/gen-abi.mjs --check  # exit 1 when the generated file or the pinned hash is out of date
//
// Why a generated JSON ABI instead of viem's parseAbi(strings): the compiled artifact is the only exact
// description of the contract (output names, `anonymous`, `indexed`, the constructor), and shipping JSON
// `as const` keeps abitype's human-readable parser out of the production bundle (SPEC §6.1 size budget).
// The Core ABI (SPEC §5.1) has no compiled artifact in this repo: its human-readable strings below are the
// source of truth and are converted to JSON with viem's parseAbi at generation time only.
import { createHash } from 'node:crypto';
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';
import { parseAbi } from 'viem';

const web = join(dirname(fileURLToPath(import.meta.url)), '..');
const repo = join(web, '..');
const artifactPath = join(repo, 'out', 'PixelPit.sol', 'PixelPit.json');
const outTs = join(web, 'src', 'abi.generated.ts');
const outHash = join(web, 'src', 'abi-hash.json');

/** SPEC §5.1 Core surface used by the page (state(), BatchSettled, implementationCodeAddress(), configuration()). */
export const CORE_ABI_STRINGS = [
  'function state() view returns ((uint64 settledThroughRound,uint64 cumulativeWork,uint96 cumulativeBlockUnits,uint64 blockHeight,uint96 blockProgress,uint32 workPerThousandBlocks,uint256 authorizationNonce,bool paused))',
  'event BatchSettled(bytes32 indexed digest,address indexed reporter,uint64 indexed settledThroughRound,uint256 nonce,uint64 previousSettledThroughRound,uint16 activeRoundCount,uint64 cumulativeWork,uint96 cumulativeBlockUnits)',
  'function implementationCodeAddress() view returns (address)',
  'function configuration() view returns ((bytes32 streamId,uint64 genesisTimestamp,uint64 roundDuration,uint64 maxWorkPerRound,uint16 maxRoundsPerBatch,address guardian,address reporter,uint32 initialWorkPerThousandBlocks,uint64 targetBlocksPerActiveRound,uint64 difficultySmoothingRounds,uint96 blockUnitsPerBlock))',
];

/** Drop `internalType` (compiler-only metadata viem ignores) so the hash is stable across refactors that only rename structs. */
export function stripInternalType(x) {
  if (Array.isArray(x)) return x.map(stripInternalType);
  if (x && typeof x === 'object') {
    const o = {};
    for (const [k, v] of Object.entries(x)) if (k !== 'internalType') o[k] = stripInternalType(v);
    return o;
  }
  return x;
}

export function sha256(text) {
  return createHash('sha256').update(text).digest('hex');
}

export function canonical(abi) {
  return JSON.stringify(abi);
}

function loadArtifact() {
  if (!existsSync(artifactPath)) {
    throw new Error(`${relative(web, artifactPath)} missing: run \`forge build\` in the repo root first`);
  }
  const art = JSON.parse(readFileSync(artifactPath, 'utf8'));
  const compiler = art.metadata?.compiler?.version ?? 'unknown';
  const settings = art.metadata?.settings ?? {};
  return {
    abi: stripInternalType(art.abi),
    compiler,
    optimizerRuns: settings.optimizer?.runs ?? null,
    evmVersion: settings.evmVersion ?? null,
    deployedBytecodeHash: art.deployedBytecode?.object ? '0x' + sha256(art.deployedBytecode.object) : null,
  };
}

export function render(pit, core, hashes) {
  const lines = [
    '// GENERATED by scripts/gen-abi.mjs — do not edit by hand. `npm run abi` regenerates, `npm run abi:check` verifies.',
    `// PixelPit: out/PixelPit.sol/PixelPit.json compiled with solc ${pit.compiler}, optimizer runs ${pit.optimizerRuns}, evm ${pit.evmVersion}.`,
    `// sha256(PixelPit ABI JSON) = ${hashes.pit}  (pinned in src/abi-hash.json)`,
    `// sha256(Core ABI JSON)     = ${hashes.core}  (SPEC §5.1 strings, see scripts/gen-abi.mjs)`,
    '',
    `export const pixelPitAbi = ${JSON.stringify(pit.abi, null, 2)} as const;`,
    '',
    `export const coreAbi = ${JSON.stringify(core, null, 2)} as const;`,
    '',
  ];
  return lines.join('\n');
}

function main() {
  const check = process.argv.includes('--check');
  const pit = loadArtifact();
  const core = stripInternalType(parseAbi(CORE_ABI_STRINGS));
  const hashes = { pit: sha256(canonical(pit.abi)), core: sha256(canonical(core)) };
  const ts = render(pit, core, hashes);
  const hashFile = {
    _comment: 'sha256 over JSON.stringify(abi) with internalType stripped; regenerate with `npm run abi` after `forge build`.',
    PixelPit: {
      sha256: hashes.pit,
      entries: pit.abi.length,
      source: 'out/PixelPit.sol/PixelPit.json',
      compiler: pit.compiler,
      optimizerRuns: pit.optimizerRuns,
      evmVersion: pit.evmVersion,
      deployedBytecodeSha256: pit.deployedBytecodeHash,
    },
    Core: { sha256: hashes.core, entries: core.length, source: 'SPEC §5.1 human-readable strings (scripts/gen-abi.mjs CORE_ABI_STRINGS)' },
  };
  const hashJson = JSON.stringify(hashFile, null, 2) + '\n';

  if (check) {
    const curTs = existsSync(outTs) ? readFileSync(outTs, 'utf8') : '';
    const curHash = existsSync(outHash) ? readFileSync(outHash, 'utf8') : '';
    const ok = curTs === ts && curHash === hashJson;
    console.log(ok ? `abi: up to date (PixelPit ${hashes.pit.slice(0, 16)}…, Core ${hashes.core.slice(0, 16)}…)` : 'abi: OUT OF DATE, run `npm run abi`');
    process.exit(ok ? 0 : 1);
  }
  writeFileSync(outTs, ts);
  writeFileSync(outHash, hashJson);
  console.log(`wrote ${relative(web, outTs)} (${pit.abi.length} PixelPit entries, ${core.length} Core entries)`);
  console.log(`sha256 PixelPit ${hashes.pit}`);
  console.log(`sha256 Core     ${hashes.core}`);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) main();
